CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK (id = 1), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, name TEXT NOT NULL, parent_id TEXT REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS apps (id TEXT PRIMARY KEY, repo_id TEXT NOT NULL UNIQUE, slug TEXT NOT NULL UNIQUE, published INTEGER NOT NULL DEFAULT 1, revision INTEGER NOT NULL DEFAULT 1, data TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS slug_aliases (slug TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES apps(id));
CREATE TABLE IF NOT EXISTS candidates (repo_id TEXT PRIMARY KEY, revision INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'pending', data TEXT NOT NULL, assessment TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS daily_additions (day TEXT PRIMARY KEY, total INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS proposals (id TEXT PRIMARY KEY, app_id TEXT NOT NULL UNIQUE REFERENCES apps(id), revision INTEGER NOT NULL DEFAULT 1, data TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS star_snapshots (repo_id TEXT NOT NULL, observed_at TEXT NOT NULL, stars INTEGER NOT NULL, PRIMARY KEY (repo_id, observed_at));
CREATE TABLE IF NOT EXISTS app_requests (id TEXT PRIMARY KEY, name TEXT NOT NULL, repo_url TEXT, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS clicks (app_id TEXT NOT NULL REFERENCES apps(id), day TEXT NOT NULL, total INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(app_id, day));
CREATE TABLE IF NOT EXISTS cost_entries (id TEXT PRIMARY KEY, period TEXT NOT NULL, provider TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount >= 0), settled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, status TEXT NOT NULL, checkpoint TEXT NOT NULL DEFAULT '{}', started_at TEXT NOT NULL, finished_at TEXT, error TEXT);
CREATE TABLE IF NOT EXISTS leases (id TEXT PRIMARY KEY, owner TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL, error TEXT);
CREATE TABLE IF NOT EXISTS search_cache (id TEXT PRIMARY KEY, data TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (id TEXT PRIMARY KEY, total INTEGER NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id TEXT PRIMARY KEY, action TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS apps_published ON apps(published);
CREATE INDEX IF NOT EXISTS costs_period ON cost_entries(period);
CREATE INDEX IF NOT EXISTS candidates_status ON candidates(status);
